import { BaseProceduralGenerator } from '../SoundGenerator';

/**
 * Creates a pristine, loopable stereo buffer with DC-offset elimination
 * and smooth equal-power boundary crossfade.
 */
function createSeamlessNoiseBuffer(
  ctx: AudioContext,
  seconds: number,
  generateChannel: (sampleRate: number, frameCount: number, channelData: Float32Array) => void
): AudioBuffer {
  const sampleRate = ctx.sampleRate;
  const frameCount = sampleRate * seconds;
  const buffer = ctx.createBuffer(2, frameCount, sampleRate);
  const dataL = buffer.getChannelData(0);
  const dataR = buffer.getChannelData(1);

  // Generate independent decorrelated noise for left and right
  generateChannel(sampleRate, frameCount, dataL);
  generateChannel(sampleRate, frameCount, dataR);

  // DC Blocking filter pass (y[n] = x[n] - x[n-1] + 0.995 * y[n-1])
  for (const data of [dataL, dataR]) {
    let lastX = 0;
    let lastY = 0;
    for (let i = 0; i < frameCount; i++) {
      const x = data[i];
      const y = x - lastX + 0.995 * lastY;
      lastX = x;
      lastY = y;
      data[i] = y;
    }

    // Equal-power crossfade at ends (100ms) for seamless infinite looping
    const crossfadeFrames = Math.floor(sampleRate * 0.1);
    for (let i = 0; i < crossfadeFrames; i++) {
      const t = i / crossfadeFrames;
      const gainStart = Math.sin((t * Math.PI) / 2);
      const gainEnd = Math.cos((t * Math.PI) / 2);
      const endIdx = frameCount - crossfadeFrames + i;
      data[i] = data[i] * gainStart + data[endIdx] * gainEnd;
    }

    // Safe normalization to prevent any digital clipping (peak at 0.40)
    let maxAbs = 0;
    for (let i = 0; i < frameCount; i++) {
      const abs = Math.abs(data[i]);
      if (abs > maxAbs) maxAbs = abs;
    }
    if (maxAbs > 0.001) {
      const normFactor = 0.40 / maxAbs;
      for (let i = 0; i < frameCount; i++) {
        data[i] *= normFactor;
      }
    }
  }

  return buffer;
}

/**
 * 1. Brown Noise Generator (Velvety, warm, deep waterfall rumble - ideal for sleep & ADHD)
 */
export class BrownNoiseGenerator extends BaseProceduralGenerator {
  private source: AudioBufferSourceNode | null = null;
  private warmFilter: BiquadFilterNode;

  constructor(id: string, ctx: AudioContext, destination: AudioNode) {
    super(id, ctx, destination);
    this.warmFilter = this.ctx.createBiquadFilter();
    this.warmFilter.type = 'lowpass';
    this.warmFilter.frequency.setValueAtTime(420, this.ctx.currentTime);
    this.warmFilter.Q.setValueAtTime(0.707, this.ctx.currentTime);
    this.warmFilter.connect(this.outputGain);
  }

  public startSynthesis(): void {
    const buffer = createSeamlessNoiseBuffer(this.ctx, 10, (_sr, frames, data) => {
      let lastVal = 0.0;
      for (let i = 0; i < frames; i++) {
        const white = Math.random() * 2 - 1;
        // Leaky integration with high damping for rich velvety low-end
        lastVal = (lastVal + 0.03 * white) / 1.03;
        data[i] = lastVal;
      }
    });

    this.source = this.ctx.createBufferSource();
    this.source.buffer = buffer;
    this.source.loop = true;
    this.source.connect(this.warmFilter);
    this.source.start();
  }

  public stopSynthesis(): void {
    if (this.source) {
      try {
        this.source.stop();
        this.source.disconnect();
      } catch {
        // ignore
      }
      this.source = null;
    }
  }
}

/**
 * 2. Pink Noise Generator (1/f equal energy per octave, Paul Kellet filter network)
 */
export class PinkNoiseGenerator extends BaseProceduralGenerator {
  private source: AudioBufferSourceNode | null = null;
  private tiltFilter: BiquadFilterNode;

  constructor(id: string, ctx: AudioContext, destination: AudioNode) {
    super(id, ctx, destination);
    this.tiltFilter = this.ctx.createBiquadFilter();
    this.tiltFilter.type = 'lowshelf';
    this.tiltFilter.frequency.setValueAtTime(1200, this.ctx.currentTime);
    this.tiltFilter.gain.setValueAtTime(-2.0, this.ctx.currentTime);
    this.tiltFilter.connect(this.outputGain);
  }

  public startSynthesis(): void {
    const buffer = createSeamlessNoiseBuffer(this.ctx, 10, (_sr, frames, data) => {
      let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
      for (let i = 0; i < frames; i++) {
        const white = Math.random() * 2 - 1;
        b0 = 0.99886 * b0 + white * 0.0555179;
        b1 = 0.99332 * b1 + white * 0.0750759;
        b2 = 0.96900 * b2 + white * 0.1538520;
        b3 = 0.86650 * b3 + white * 0.3104856;
        b4 = 0.55000 * b4 + white * 0.5329522;
        b5 = -0.7616 * b5 - white * 0.0168980;
        data[i] = b0 + b1 + b2 + b3 + b4 + b5 + b6 + white * 0.5362;
        b6 = white * 0.115926;
      }
    });

    this.source = this.ctx.createBufferSource();
    this.source.buffer = buffer;
    this.source.loop = true;
    this.source.connect(this.tiltFilter);
    this.source.start();
  }

  public stopSynthesis(): void {
    if (this.source) {
      try {
        this.source.stop();
        this.source.disconnect();
      } catch {
        // ignore
      }
      this.source = null;
    }
  }
}

/**
 * 3. White Noise Generator (Full spectrum acoustic masking with gentle ear-fatigue roll-off)
 */
export class WhiteNoiseGenerator extends BaseProceduralGenerator {
  private source: AudioBufferSourceNode | null = null;
  private deHarshFilter: BiquadFilterNode;

  constructor(id: string, ctx: AudioContext, destination: AudioNode) {
    super(id, ctx, destination);
    this.deHarshFilter = this.ctx.createBiquadFilter();
    this.deHarshFilter.type = 'lowpass';
    this.deHarshFilter.frequency.setValueAtTime(7500, this.ctx.currentTime); // prevents piercing harshness
    this.deHarshFilter.connect(this.outputGain);
  }

  public startSynthesis(): void {
    const buffer = createSeamlessNoiseBuffer(this.ctx, 8, (_sr, frames, data) => {
      for (let i = 0; i < frames; i++) {
        data[i] = Math.random() * 2 - 1;
      }
    });

    this.source = this.ctx.createBufferSource();
    this.source.buffer = buffer;
    this.source.loop = true;
    this.source.connect(this.deHarshFilter);
    this.source.start();
  }

  public stopSynthesis(): void {
    if (this.source) {
      try {
        this.source.stop();
        this.source.disconnect();
      } catch {
        // ignore
      }
      this.source = null;
    }
  }
}

/**
 * 4. Green Noise Generator (Center-peaked around 480 Hz like natural mountain breeze & waterfalls)
 */
export class GreenNoiseGenerator extends BaseProceduralGenerator {
  private source: AudioBufferSourceNode | null = null;
  private peakFilter: BiquadFilterNode;
  private lowpassFilter: BiquadFilterNode;

  constructor(id: string, ctx: AudioContext, destination: AudioNode) {
    super(id, ctx, destination);

    this.peakFilter = this.ctx.createBiquadFilter();
    this.peakFilter.type = 'peaking';
    this.peakFilter.frequency.setValueAtTime(480, this.ctx.currentTime);
    this.peakFilter.Q.setValueAtTime(0.9, this.ctx.currentTime);
    this.peakFilter.gain.setValueAtTime(4.0, this.ctx.currentTime);

    this.lowpassFilter = this.ctx.createBiquadFilter();
    this.lowpassFilter.type = 'lowpass';
    this.lowpassFilter.frequency.setValueAtTime(1400, this.ctx.currentTime);

    this.peakFilter.connect(this.lowpassFilter);
    this.lowpassFilter.connect(this.outputGain);
  }

  public startSynthesis(): void {
    const buffer = createSeamlessNoiseBuffer(this.ctx, 10, (_sr, frames, data) => {
      let b0 = 0, b1 = 0, b2 = 0;
      for (let i = 0; i < frames; i++) {
        const white = Math.random() * 2 - 1;
        b0 = 0.985 * b0 + white * 0.09;
        b1 = 0.940 * b1 + white * 0.16;
        b2 = 0.830 * b2 + white * 0.24;
        data[i] = (b0 + b1 + b2) * 0.33;
      }
    });

    this.source = this.ctx.createBufferSource();
    this.source.buffer = buffer;
    this.source.loop = true;
    this.source.connect(this.peakFilter);
    this.source.start();
  }

  public stopSynthesis(): void {
    if (this.source) {
      try {
        this.source.stop();
        this.source.disconnect();
      } catch {
        // ignore
      }
      this.source = null;
    }
  }
}
