export interface ISoundGenerator {
  id: string;
  start(): void;
  stop(): void;
  setVolume(volume: number, rampTime?: number): void;
  setMute(isMuted: boolean): void;
  isPlaying(): boolean;
  dispose(): void;
}

export abstract class BaseProceduralGenerator implements ISoundGenerator {
  public readonly id: string;
  protected ctx: AudioContext;
  protected destinationNode: AudioNode;
  protected outputGain: GainNode;
  protected volume: number = 0.5;
  protected muted: boolean = false;
  protected running: boolean = false;

  constructor(id: string, ctx: AudioContext, destination: AudioNode) {
    this.id = id;
    this.ctx = ctx;
    this.destinationNode = destination;

    this.outputGain = this.ctx.createGain();
    this.outputGain.gain.setValueAtTime(0, this.ctx.currentTime);
    this.outputGain.connect(this.destinationNode);
  }

  public abstract startSynthesis(): void;
  public abstract stopSynthesis(): void;

  public start(): void {
    if (this.running) return;
    this.running = true;
    this.startSynthesis();
    this.applyGain(0.08); // smooth fade-in
  }

  public stop(): void {
    if (!this.running) return;
    this.running = false;
    const now = this.ctx.currentTime;
    this.outputGain.gain.cancelScheduledValues(now);
    this.outputGain.gain.setValueAtTime(this.outputGain.gain.value, now);
    this.outputGain.gain.linearRampToValueAtTime(0.0001, now + 0.1);
    setTimeout(() => {
      if (!this.running) {
        this.stopSynthesis();
      }
    }, 120);
  }

  public setVolume(volume: number, rampTime: number = 0.05): void {
    this.volume = Math.max(0, Math.min(1, volume));
    if (this.running && !this.muted) {
      this.applyGain(rampTime);
    }
  }

  public setMute(isMuted: boolean): void {
    this.muted = isMuted;
    if (this.running) {
      this.applyGain(0.05);
    }
  }

  protected applyGain(rampTime: number = 0.05): void {
    const target = this.muted ? 0.0001 : Math.max(0.0001, this.volume);
    const now = this.ctx.currentTime;
    this.outputGain.gain.cancelScheduledValues(now);
    this.outputGain.gain.setValueAtTime(this.outputGain.gain.value, now);
    this.outputGain.gain.exponentialRampToValueAtTime(target, now + rampTime);
  }

  public isPlaying(): boolean {
    return this.running;
  }

  public dispose(): void {
    this.stop();
    this.outputGain.disconnect();
  }
}
