import { BaseProceduralGenerator } from '../SoundGenerator';

/**
 * 12. Binaural Alpha Waves (10 Hz Flow State & Focus)
 * Embedded in a warm, meditative ambient drone sound bath (F2 chord: 87.3 Hz / 174.6 Hz)
 * Left Ear: 170 Hz, Right Ear: 180 Hz (10 Hz beat difference)
 * Warm, soothing, and zero laboratory harshness.
 */
export class BinauralAlphaGenerator extends BaseProceduralGenerator {
  private oscL: OscillatorNode | null = null;
  private oscR: OscillatorNode | null = null;
  private droneOsc: OscillatorNode | null = null;
  private merger: ChannelMergerNode | null = null;
  private warmthFilter: BiquadFilterNode | null = null;

  public startSynthesis(): void {
    const now = this.ctx.currentTime;

    this.oscL = this.ctx.createOscillator();
    this.oscR = this.ctx.createOscillator();
    this.droneOsc = this.ctx.createOscillator();

    this.oscL.type = 'sine';
    this.oscR.type = 'sine';
    this.droneOsc.type = 'triangle'; // rich, warm harmonic sub

    // 170 Hz (L) and 180 Hz (R) => 10 Hz Alpha Entrainment
    this.oscL.frequency.setValueAtTime(170, now);
    this.oscR.frequency.setValueAtTime(180, now);
    this.droneOsc.frequency.setValueAtTime(85, now); // Warm octave root

    this.warmthFilter = this.ctx.createBiquadFilter();
    this.warmthFilter.type = 'lowpass';
    this.warmthFilter.frequency.setValueAtTime(450, now);

    const gainL = this.ctx.createGain();
    const gainR = this.ctx.createGain();
    const gainDrone = this.ctx.createGain();

    gainL.gain.setValueAtTime(0.20, now);
    gainR.gain.setValueAtTime(0.20, now);
    gainDrone.gain.setValueAtTime(0.12, now);

    this.merger = this.ctx.createChannelMerger(2);

    this.oscL.connect(gainL);
    this.oscR.connect(gainR);
    this.droneOsc.connect(gainDrone);

    gainL.connect(this.merger, 0, 0); // Left
    gainR.connect(this.merger, 0, 1); // Right
    gainDrone.connect(this.merger, 0, 0);
    gainDrone.connect(this.merger, 0, 1);

    this.merger.connect(this.warmthFilter);
    this.warmthFilter.connect(this.outputGain);

    this.oscL.start();
    this.oscR.start();
    this.droneOsc.start();
  }

  public stopSynthesis(): void {
    if (this.oscL) {
      try { this.oscL.stop(); this.oscL.disconnect(); } catch { /* ignore */ }
      this.oscL = null;
    }
    if (this.oscR) {
      try { this.oscR.stop(); this.oscR.disconnect(); } catch { /* ignore */ }
      this.oscR = null;
    }
    if (this.droneOsc) {
      try { this.droneOsc.stop(); this.droneOsc.disconnect(); } catch { /* ignore */ }
      this.droneOsc = null;
    }
  }
}

/**
 * 13. Binaural Delta Waves (3 Hz Deep REM Sleep)
 * Left Ear: 108 Hz, Right Ear: 111 Hz (3 Hz Delta Entrainment)
 * Layered with a velvety 54 Hz sub-drone.
 */
export class BinauralDeltaGenerator extends BaseProceduralGenerator {
  private oscL: OscillatorNode | null = null;
  private oscR: OscillatorNode | null = null;
  private subOsc: OscillatorNode | null = null;
  private merger: ChannelMergerNode | null = null;
  private warmthFilter: BiquadFilterNode | null = null;

  public startSynthesis(): void {
    const now = this.ctx.currentTime;

    this.oscL = this.ctx.createOscillator();
    this.oscR = this.ctx.createOscillator();
    this.subOsc = this.ctx.createOscillator();

    this.oscL.type = 'sine';
    this.oscR.type = 'sine';
    this.subOsc.type = 'sine';

    // 108 Hz (L) and 111 Hz (R) => 3 Hz Delta
    this.oscL.frequency.setValueAtTime(108, now);
    this.oscR.frequency.setValueAtTime(111, now);
    this.subOsc.frequency.setValueAtTime(54, now);

    this.warmthFilter = this.ctx.createBiquadFilter();
    this.warmthFilter.type = 'lowpass';
    this.warmthFilter.frequency.setValueAtTime(320, now);

    const gainL = this.ctx.createGain();
    const gainR = this.ctx.createGain();
    const gainSub = this.ctx.createGain();

    gainL.gain.setValueAtTime(0.22, now);
    gainR.gain.setValueAtTime(0.22, now);
    gainSub.gain.setValueAtTime(0.15, now);

    this.merger = this.ctx.createChannelMerger(2);

    this.oscL.connect(gainL);
    this.oscR.connect(gainR);
    this.subOsc.connect(gainSub);

    gainL.connect(this.merger, 0, 0);
    gainR.connect(this.merger, 0, 1);
    gainSub.connect(this.merger, 0, 0);
    gainSub.connect(this.merger, 0, 1);

    this.merger.connect(this.warmthFilter);
    this.warmthFilter.connect(this.outputGain);

    this.oscL.start();
    this.oscR.start();
    this.subOsc.start();
  }

  public stopSynthesis(): void {
    if (this.oscL) {
      try { this.oscL.stop(); this.oscL.disconnect(); } catch { /* ignore */ }
      this.oscL = null;
    }
    if (this.oscR) {
      try { this.oscR.stop(); this.oscR.disconnect(); } catch { /* ignore */ }
      this.oscR = null;
    }
    if (this.subOsc) {
      try { this.subOsc.stop(); this.subOsc.disconnect(); } catch { /* ignore */ }
      this.subOsc = null;
    }
  }
}

/**
 * 14. Mechanical Train
 * Hypnotic rhythm of steel on rails ("clack-clack") with wooden railway tie dampening.
 */
export class MechanicalTrainGenerator extends BaseProceduralGenerator {
  private rumbleSource: AudioBufferSourceNode | null = null;
  private trainTimer: number | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;
    const frames = sr * 6;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    let lastL = 0, lastR = 0;
    for (let i = 0; i < frames; i++) {
      lastL = (lastL + 0.04 * (Math.random() * 2 - 1)) / 1.04;
      lastR = (lastR + 0.04 * (Math.random() * 2 - 1)) / 1.04;
      l[i] = lastL * 1.8;
      r[i] = lastR * 1.8;
    }

    const lp = this.ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.setValueAtTime(140, this.ctx.currentTime);

    this.rumbleSource = this.ctx.createBufferSource();
    this.rumbleSource.buffer = buffer;
    this.rumbleSource.loop = true;
    this.rumbleSource.connect(lp);
    lp.connect(this.outputGain);
    this.rumbleSource.start();

    this.scheduleTrainCycle();
  }

  private scheduleTrainCycle(): void {
    if (!this.running) return;

    // Front bogie clack-clack, then rear bogie clack-clack
    this.triggerAcousticRailTap(0.00, 0.22);
    this.triggerAcousticRailTap(0.14, 0.16);
    this.triggerAcousticRailTap(0.50, 0.20);
    this.triggerAcousticRailTap(0.64, 0.15);

    this.trainTimer = window.setTimeout(() => this.scheduleTrainCycle(), 1480);
  }

  private triggerAcousticRailTap(delaySec: number, intensity: number): void {
    const now = this.ctx.currentTime + delaySec;
    const dur = 0.04;

    const osc = this.ctx.createOscillator();
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();

    osc.type = 'triangle';
    osc.frequency.setValueAtTime(180, now);
    osc.frequency.exponentialRampToValueAtTime(50, now + dur);

    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(450, now);
    filter.Q.setValueAtTime(2.0, now);

    gain.gain.setValueAtTime(intensity, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur);

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + dur);
  }

  public stopSynthesis(): void {
    if (this.trainTimer) {
      clearTimeout(this.trainTimer);
      this.trainTimer = null;
    }
    if (this.rumbleSource) {
      try { this.rumbleSource.stop(); this.rumbleSource.disconnect(); } catch { /* ignore */ }
      this.rumbleSource = null;
    }
  }
}

/**
 * 15. Clock Ticking
 * Warm wooden grandfather clock escapement at 60 BPM (1.0 Hz).
 * Mellow, acoustic, and reassuring.
 */
export class ClockTickingGenerator extends BaseProceduralGenerator {
  private clockTimer: number | null = null;
  private isTick: boolean = true;

  public startSynthesis(): void {
    this.scheduleTick();
  }

  private scheduleTick(): void {
    if (!this.running) return;

    const now = this.ctx.currentTime;
    const dur = 0.025;

    const osc = this.ctx.createOscillator();
    const filter = this.ctx.createBiquadFilter();
    const gain = this.ctx.createGain();

    osc.type = 'sine';
    const freq = this.isTick ? 1120 : 780;
    this.isTick = !this.isTick;

    osc.frequency.setValueAtTime(freq, now);
    osc.frequency.exponentialRampToValueAtTime(280, now + dur);

    filter.type = 'bandpass';
    filter.frequency.setValueAtTime(freq, now);
    filter.Q.setValueAtTime(4.5, now);

    gain.gain.setValueAtTime(0.12, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + dur);

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + dur);

    this.clockTimer = window.setTimeout(() => this.scheduleTick(), 1000);
  }

  public stopSynthesis(): void {
    if (this.clockTimer) {
      clearTimeout(this.clockTimer);
      this.clockTimer = null;
    }
  }
}
