import { ISoundGenerator } from './SoundGenerator';
import {
  BrownNoiseGenerator,
  PinkNoiseGenerator,
  WhiteNoiseGenerator,
  GreenNoiseGenerator
} from './generators/NoiseGenerators';
import {
  HeavyRainGenerator,
  DistantThunderGenerator,
  OceanWavesGenerator,
  CozyFireplaceGenerator,
  ForestWindGenerator,
  NightCricketsGenerator,
  MountainStreamGenerator
} from './generators/NatureGenerators';
import {
  BinauralAlphaGenerator,
  BinauralDeltaGenerator,
  MechanicalTrainGenerator,
  ClockTickingGenerator
} from './generators/MindGenerators';
import { SOUND_DEFINITIONS, DEFAULT_PRESETS } from './Presets';
import { PresetDefinition } from '../types';

export class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private limiter: DynamicsCompressorNode | null = null;
  private analyser: AnalyserNode | null = null;

  private generators: Map<string, ISoundGenerator> = new Map();
  private masterVolume: number = 0.8;
  private isMuted: boolean = false;
  private originalMasterVolumeBeforeFade: number = 0.8;

  // Sleep timer properties
  private timerDurationSeconds: number = 0;
  private timerRemainingSeconds: number = 0;
  private timerIntervalId: number | null = null;
  private isTimerRunning: boolean = false;
  private fadeDurationSeconds: number = 60;
  private onTimerTickCallback: ((remaining: number, isFading: boolean) => void) | null = null;
  private onTimerEndCallback: (() => void) | null = null;
  private onStateChangeCallback: (() => void) | null = null;
  private silentAudio: HTMLAudioElement | null = null;

  constructor() {
    // Lazy initialized on first user interaction to comply with browser autoplay policy
  }

  public initContext(): AudioContext {
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.ctx = new AudioCtx();

      // 1. DC Blocking High-Pass Filter (removes sub-audible DC offset to prevent distortion)
      const dcBlocker = this.ctx.createBiquadFilter();
      dcBlocker.type = 'highpass';
      dcBlocker.frequency.setValueAtTime(18, this.ctx.currentTime);
      dcBlocker.Q.setValueAtTime(0.707, this.ctx.currentTime);

      // 2. Master Limiter / Transparent Mastering Compressor (no pumping, no distortion)
      this.limiter = this.ctx.createDynamicsCompressor();
      this.limiter.threshold.setValueAtTime(-6.0, this.ctx.currentTime);
      this.limiter.knee.setValueAtTime(18.0, this.ctx.currentTime); // very soft musical knee
      this.limiter.ratio.setValueAtTime(2.5, this.ctx.currentTime);  // transparent, uncrushed dynamics
      this.limiter.attack.setValueAtTime(0.04, this.ctx.currentTime); // 40ms transparent attack
      this.limiter.release.setValueAtTime(0.25, this.ctx.currentTime);

      // 3. Analyser Node for 60 FPS Visualizer
      this.analyser = this.ctx.createAnalyser();
      this.analyser.fftSize = 256;
      this.analyser.smoothingTimeConstant = 0.85;

      // 4. Master Gain
      this.masterGain = this.ctx.createGain();
      this.masterGain.gain.setValueAtTime(this.masterVolume, this.ctx.currentTime);

      // Routing: Generators -> MasterGain -> DCBlocker -> Limiter -> Analyser -> Destination
      this.masterGain.connect(dcBlocker);
      dcBlocker.connect(this.limiter);
      this.limiter.connect(this.analyser);
      this.analyser.connect(this.ctx.destination);

      // Initialize all 15 generators
      this.initGenerators();

      // Setup iOS Background Audio keep-alive and Lock Screen MediaSession
      this.initBackgroundAudioSession();
    }

    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }

    return this.ctx;
  }

  private initGenerators(): void {
    if (!this.ctx || !this.masterGain) return;

    const gMap: Record<string, () => ISoundGenerator> = {
      'brown-noise': () => new BrownNoiseGenerator('brown-noise', this.ctx!, this.masterGain!),
      'pink-noise': () => new PinkNoiseGenerator('pink-noise', this.ctx!, this.masterGain!),
      'white-noise': () => new WhiteNoiseGenerator('white-noise', this.ctx!, this.masterGain!),
      'green-noise': () => new GreenNoiseGenerator('green-noise', this.ctx!, this.masterGain!),

      'heavy-rain': () => new HeavyRainGenerator('heavy-rain', this.ctx!, this.masterGain!),
      'distant-thunder': () => new DistantThunderGenerator('distant-thunder', this.ctx!, this.masterGain!),
      'ocean-waves': () => new OceanWavesGenerator('ocean-waves', this.ctx!, this.masterGain!),
      'cozy-fireplace': () => new CozyFireplaceGenerator('cozy-fireplace', this.ctx!, this.masterGain!),
      'forest-wind': () => new ForestWindGenerator('forest-wind', this.ctx!, this.masterGain!),
      'night-crickets': () => new NightCricketsGenerator('night-crickets', this.ctx!, this.masterGain!),
      'mountain-stream': () => new MountainStreamGenerator('mountain-stream', this.ctx!, this.masterGain!),

      'binaural-alpha': () => new BinauralAlphaGenerator('binaural-alpha', this.ctx!, this.masterGain!),
      'binaural-delta': () => new BinauralDeltaGenerator('binaural-delta', this.ctx!, this.masterGain!),
      'mechanical-train': () => new MechanicalTrainGenerator('mechanical-train', this.ctx!, this.masterGain!),
      'clock-ticking': () => new ClockTickingGenerator('clock-ticking', this.ctx!, this.masterGain!)
    };

    SOUND_DEFINITIONS.forEach(def => {
      if (gMap[def.id]) {
        this.generators.set(def.id, gMap[def.id]());
      }
    });
  }

  public getAnalyser(): AnalyserNode | null {
    return this.analyser;
  }

  public setOnStateChange(cb: () => void): void {
    this.onStateChangeCallback = cb;
  }

  public setOnTimerTick(cb: (remaining: number, isFading: boolean) => void): void {
    this.onTimerTickCallback = cb;
  }

  public setOnTimerEnd(cb: () => void): void {
    this.onTimerEndCallback = cb;
  }

  public startSound(id: string, volume: number = 0.5): void {
    this.initContext();
    const gen = this.generators.get(id);
    if (gen) {
      gen.setVolume(volume);
      gen.start();
      this.triggerStateChange();
    }
  }

  public stopSound(id: string): void {
    const gen = this.generators.get(id);
    if (gen) {
      gen.stop();
      this.triggerStateChange();
    }
  }

  public toggleSound(id: string, defaultVolume: number = 0.5): boolean {
    this.initContext();
    const gen = this.generators.get(id);
    if (!gen) return false;

    if (gen.isPlaying()) {
      gen.stop();
      this.triggerStateChange();
      return false;
    } else {
      gen.setVolume(defaultVolume);
      gen.start();
      this.triggerStateChange();
      return true;
    }
  }

  public setSoundVolume(id: string, volume: number): void {
    const gen = this.generators.get(id);
    if (gen) {
      gen.setVolume(volume);
      this.triggerStateChange();
    }
  }

  public setSoundMute(id: string, isMuted: boolean): void {
    const gen = this.generators.get(id);
    if (gen) {
      gen.setMute(isMuted);
      this.triggerStateChange();
    }
  }

  public isSoundPlaying(id: string): boolean {
    return this.generators.get(id)?.isPlaying() ?? false;
  }

  public getActiveCount(): number {
    let count = 0;
    this.generators.forEach(gen => {
      if (gen.isPlaying()) count++;
    });
    return count;
  }

  public stopAll(): void {
    this.generators.forEach(gen => {
      if (gen.isPlaying()) {
        gen.stop();
      }
    });
    this.triggerStateChange();
  }

  public setMasterVolume(vol: number): void {
    this.masterVolume = Math.max(0, Math.min(1, vol));
    this.originalMasterVolumeBeforeFade = this.masterVolume;
    if (this.masterGain && this.ctx && !this.isMuted) {
      const now = this.ctx.currentTime;
      this.masterGain.gain.cancelScheduledValues(now);
      this.masterGain.gain.setValueAtTime(this.masterGain.gain.value, now);
      this.masterGain.gain.linearRampToValueAtTime(this.masterVolume, now + 0.05);
    }
  }

  public getMasterVolume(): number {
    return this.masterVolume;
  }

  public toggleMasterMute(): boolean {
    this.isMuted = !this.isMuted;
    if (this.masterGain && this.ctx) {
      const now = this.ctx.currentTime;
      const target = this.isMuted ? 0.0001 : this.masterVolume;
      this.masterGain.gain.cancelScheduledValues(now);
      this.masterGain.gain.setValueAtTime(this.masterGain.gain.value, now);
      this.masterGain.gain.linearRampToValueAtTime(target, now + 0.08);
    }
    return this.isMuted;
  }

  public applyPreset(preset: PresetDefinition): void {
    this.initContext();
    // Stop sounds not in preset
    this.generators.forEach((gen, id) => {
      if (preset.sounds[id] === undefined && gen.isPlaying()) {
        gen.stop();
      }
    });

    // Start or set sounds in preset
    Object.entries(preset.sounds).forEach(([id, vol]) => {
      const gen = this.generators.get(id);
      if (gen) {
        gen.setVolume(vol);
        if (!gen.isPlaying()) {
          gen.start();
        }
      }
    });

    this.triggerStateChange();
  }

  // --- Smart Sleep Timer with Exponential Soft Fade-out ---
  public startTimer(durationMinutes: number): void {
    this.stopTimer();
    this.timerDurationSeconds = Math.round(durationMinutes * 60);
    this.timerRemainingSeconds = this.timerDurationSeconds;
    this.isTimerRunning = true;
    this.originalMasterVolumeBeforeFade = this.masterVolume;

    this.timerIntervalId = window.setInterval(() => {
      this.tickTimer();
    }, 1000);

    if (this.onTimerTickCallback) {
      this.onTimerTickCallback(this.timerRemainingSeconds, false);
    }
  }

  private tickTimer(): void {
    if (!this.isTimerRunning) return;

    this.timerRemainingSeconds--;

    const isFading = this.timerRemainingSeconds <= this.fadeDurationSeconds && this.timerRemainingSeconds > 0;

    if (isFading && this.masterGain && this.ctx) {
      // Exponential fadeout over last 60 seconds (or remaining time)
      const fadeProgress = this.timerRemainingSeconds / this.fadeDurationSeconds;
      // Exponential curve: progress^2 for natural acoustic decay
      const fadedGain = Math.max(0.0001, this.originalMasterVolumeBeforeFade * (fadeProgress * fadeProgress));
      const now = this.ctx.currentTime;
      this.masterGain.gain.cancelScheduledValues(now);
      this.masterGain.gain.setValueAtTime(this.masterGain.gain.value, now);
      this.masterGain.gain.linearRampToValueAtTime(fadedGain, now + 0.8);
    }

    if (this.onTimerTickCallback) {
      this.onTimerTickCallback(this.timerRemainingSeconds, isFading);
    }

    if (this.timerRemainingSeconds <= 0) {
      this.completeTimer();
    }
  }

  public stopTimer(): void {
    if (this.timerIntervalId !== null) {
      clearInterval(this.timerIntervalId);
      this.timerIntervalId = null;
    }
    this.isTimerRunning = false;
    this.timerRemainingSeconds = 0;

    // Restore original master volume if it was fading
    if (this.masterGain && this.ctx) {
      const now = this.ctx.currentTime;
      this.masterGain.gain.cancelScheduledValues(now);
      this.masterGain.gain.linearRampToValueAtTime(this.originalMasterVolumeBeforeFade, now + 0.1);
    }
  }

  private completeTimer(): void {
    this.stopTimer();
    this.stopAll();
    if (this.onTimerEndCallback) {
      this.onTimerEndCallback();
    }
  }

  public getTimerRemaining(): number {
    return this.timerRemainingSeconds;
  }

  public isTimerActive(): boolean {
    return this.isTimerRunning;
  }

  private triggerStateChange(): void {
    this.updateBackgroundAudioState();
    if (this.onStateChangeCallback) {
      this.onStateChangeCallback();
    }
  }

  private initBackgroundAudioSession(): void {
    if (typeof document === 'undefined') return;

    // Silent looping audio track keeps iOS WebKit audio thread active when screen locks
    if (!this.silentAudio) {
      this.silentAudio = document.createElement('audio');
      // 1-second inaudible PCM silence
      this.silentAudio.src = 'data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEARKwAAIhYAQACABAAAABkYXRhAgAAAAEA';
      this.silentAudio.loop = true;
    }

    if (typeof navigator !== 'undefined' && 'mediaSession' in navigator) {
      navigator.mediaSession.metadata = new MediaMetadata({
        title: 'ZenWave',
        artist: 'Ambient Sleep & Deep Focus',
        album: 'Procedural Soundscapes'
      });

      navigator.mediaSession.setActionHandler('play', () => {
        const defaultPreset = DEFAULT_PRESETS[0];
        this.applyPreset(defaultPreset);
      });

      navigator.mediaSession.setActionHandler('pause', () => {
        this.stopAll();
      });

      navigator.mediaSession.setActionHandler('stop', () => {
        this.stopAll();
      });
    }
  }

  private updateBackgroundAudioState(): void {
    const isPlaying = this.getActiveCount() > 0;
    if (this.silentAudio) {
      if (isPlaying) {
        this.silentAudio.play().catch(() => {});
      } else {
        this.silentAudio.pause();
      }
    }

    if (typeof navigator !== 'undefined' && 'mediaSession' in navigator) {
      navigator.mediaSession.playbackState = isPlaying ? 'playing' : 'paused';
    }
  }
}
