import { BaseProceduralGenerator } from '../SoundGenerator';

/**
 * 5. Heavy Rain Generator
 * Multi-layer acoustic rain: Soft rain bed + hundreds of stochastic acoustic droplet impacts.
 * Pure filtered noise dynamics — ZERO synthetic sine chirps.
 */
export class HeavyRainGenerator extends BaseProceduralGenerator {
  private bedSource: AudioBufferSourceNode | null = null;
  private dropTimer: number | null = null;
  private dropImpulseBuffer: AudioBuffer | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;

    // 1. Warm background rain shower bed (10-second seamless loop)
    const bedDuration = 10;
    const bedFrames = sr * bedDuration;
    const bedBuffer = this.ctx.createBuffer(2, bedFrames, sr);
    const bedL = bedBuffer.getChannelData(0);
    const bedR = bedBuffer.getChannelData(1);

    let l1 = 0, l2 = 0, r1 = 0, r2 = 0;
    for (let i = 0; i < bedFrames; i++) {
      const wL = Math.random() * 2 - 1;
      const wR = Math.random() * 2 - 1;
      l1 = 0.94 * l1 + wL * 0.06;
      l2 = 0.88 * l2 + l1 * 0.12;
      r1 = 0.94 * r1 + wR * 0.06;
      r2 = 0.88 * r2 + r1 * 0.12;
      bedL[i] = l2 * 1.4;
      bedR[i] = r2 * 1.4;
    }

    // Gentle high-shelf roll-off for warm acoustic rain
    const bedFilter = this.ctx.createBiquadFilter();
    bedFilter.type = 'lowpass';
    bedFilter.frequency.setValueAtTime(3200, this.ctx.currentTime);

    this.bedSource = this.ctx.createBufferSource();
    this.bedSource.buffer = bedBuffer;
    this.bedSource.loop = true;
    this.bedSource.connect(bedFilter);
    bedFilter.connect(this.outputGain);
    this.bedSource.start();

    // 2. Pre-generate acoustic droplet impulses (noise-based, NO synthetic sines)
    const impulseFrames = Math.floor(sr * 0.04); // 40ms droplet impact
    this.dropImpulseBuffer = this.ctx.createBuffer(1, impulseFrames, sr);
    const impData = this.dropImpulseBuffer.getChannelData(0);
    for (let i = 0; i < impulseFrames; i++) {
      const decay = Math.exp(-i / (sr * 0.008));
      impData[i] = (Math.random() * 2 - 1) * decay;
    }

    this.scheduleDroplets();
  }

  private scheduleDroplets(): void {
    if (!this.running) return;

    // Stochastic drops hitting leaves, glass, and ground
    const count = Math.floor(Math.random() * 4) + 2;
    for (let i = 0; i < count; i++) {
      const delay = Math.random() * 80;
      setTimeout(() => {
        if (!this.running || !this.dropImpulseBuffer) return;
        this.triggerAcousticDrop();
      }, delay);
    }

    const nextBatch = 40 + Math.random() * 60;
    this.dropTimer = window.setTimeout(() => this.scheduleDroplets(), nextBatch);
  }

  private triggerAcousticDrop(): void {
    if (!this.dropImpulseBuffer) return;
    const now = this.ctx.currentTime;

    const source = this.ctx.createBufferSource();
    source.buffer = this.dropImpulseBuffer;

    // Resonant bandpass filter tuned to surface impact frequency (1.2k - 3.8k Hz)
    const bp = this.ctx.createBiquadFilter();
    bp.type = 'bandpass';
    const centerFreq = 1200 + Math.random() * 2400;
    bp.frequency.setValueAtTime(centerFreq, now);
    bp.Q.setValueAtTime(3.5 + Math.random() * 3.0, now);

    const gain = this.ctx.createGain();
    const amp = 0.08 + Math.random() * 0.10;
    gain.gain.setValueAtTime(amp, now);

    const pan = this.ctx.createStereoPanner();
    pan.pan.setValueAtTime(Math.random() * 1.6 - 0.8, now);

    source.connect(bp);
    bp.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    source.start(now);
  }

  public stopSynthesis(): void {
    if (this.dropTimer) {
      clearTimeout(this.dropTimer);
      this.dropTimer = null;
    }
    if (this.bedSource) {
      try {
        this.bedSource.stop();
        this.bedSource.disconnect();
      } catch {
        // ignore
      }
      this.bedSource = null;
    }
  }
}

/**
 * 6. Distant Thunder Generator
 * Deep atmospheric sub-bass shockwave and rolling cloud reverberation (35 Hz - 85 Hz).
 */
export class DistantThunderGenerator extends BaseProceduralGenerator {
  private thunderTimer: number | null = null;
  private rumbleBuffer: AudioBuffer | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;
    const frames = sr * 8;
    this.rumbleBuffer = this.ctx.createBuffer(2, frames, sr);
    const l = this.rumbleBuffer.getChannelData(0);
    const r = this.rumbleBuffer.getChannelData(1);

    let lastL = 0, lastR = 0;
    for (let i = 0; i < frames; i++) {
      lastL = (lastL + 0.02 * (Math.random() * 2 - 1)) / 1.02;
      lastR = (lastR + 0.02 * (Math.random() * 2 - 1)) / 1.02;
      l[i] = lastL;
      r[i] = lastR;
    }

    setTimeout(() => {
      if (this.running) this.triggerThunder();
    }, 1500);

    this.scheduleNext();
  }

  private scheduleNext(): void {
    if (!this.running) return;
    const nextInterval = 16000 + Math.random() * 16000;
    this.thunderTimer = window.setTimeout(() => {
      if (!this.running) return;
      this.triggerThunder();
      this.scheduleNext();
    }, nextInterval);
  }

  private triggerThunder(): void {
    if (!this.rumbleBuffer) return;
    const now = this.ctx.currentTime;
    const duration = 6.0 + Math.random() * 2.5;

    const source = this.ctx.createBufferSource();
    source.buffer = this.rumbleBuffer;

    const lowpass = this.ctx.createBiquadFilter();
    lowpass.type = 'lowpass';
    lowpass.frequency.setValueAtTime(110, now);
    lowpass.frequency.exponentialRampToValueAtTime(55, now + duration);

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    // Smooth natural attack over 0.8s, secondary roll over 2.5s, slow fade
    gain.gain.linearRampToValueAtTime(0.35, now + 0.7);
    gain.gain.linearRampToValueAtTime(0.28, now + 2.2);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    const pan = this.ctx.createStereoPanner();
    pan.pan.setValueAtTime(Math.random() * 1.2 - 0.6, now);

    source.connect(lowpass);
    lowpass.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    source.start(now);
    source.stop(now + duration);
  }

  public stopSynthesis(): void {
    if (this.thunderTimer) {
      clearTimeout(this.thunderTimer);
      this.thunderTimer = null;
    }
  }
}

/**
 * 7. Ocean Waves Generator
 * 14-second organic coastal swell: Deep tidal build-up -> foamy wash crest -> gentle recession.
 */
export class OceanWavesGenerator extends BaseProceduralGenerator {
  private noiseSource: AudioBufferSourceNode | null = null;
  private lfo1: OscillatorNode | null = null;
  private lfo2: OscillatorNode | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;
    const frames = sr * 12;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    let lastL = 0, lastR = 0;
    for (let i = 0; i < frames; i++) {
      lastL = (lastL + 0.025 * (Math.random() * 2 - 1)) / 1.025;
      lastR = (lastR + 0.025 * (Math.random() * 2 - 1)) / 1.025;
      l[i] = lastL * 2.8;
      r[i] = lastR * 2.8;
    }

    this.noiseSource = this.ctx.createBufferSource();
    this.noiseSource.buffer = buffer;
    this.noiseSource.loop = true;

    // Resonant wave filter sweeping with tidal cycle
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(280, this.ctx.currentTime);
    filter.Q.setValueAtTime(1.4, this.ctx.currentTime);

    // LFO: 0.07 Hz (~14.2s natural tidal rhythm)
    this.lfo1 = this.ctx.createOscillator();
    this.lfo1.type = 'sine';
    this.lfo1.frequency.setValueAtTime(0.07, this.ctx.currentTime);

    const lfoFilterGain = this.ctx.createGain();
    lfoFilterGain.gain.setValueAtTime(220, this.ctx.currentTime);
    this.lfo1.connect(lfoFilterGain);
    lfoFilterGain.connect(filter.frequency);

    this.lfo2 = this.ctx.createOscillator();
    this.lfo2.type = 'sine';
    this.lfo2.frequency.setValueAtTime(0.07, this.ctx.currentTime);

    const ampMod = this.ctx.createGain();
    ampMod.gain.setValueAtTime(0.35, this.ctx.currentTime);
    this.lfo2.connect(ampMod.gain);

    this.noiseSource.connect(filter);
    filter.connect(ampMod);
    ampMod.connect(this.outputGain);

    this.noiseSource.start();
    this.lfo1.start();
    this.lfo2.start();
  }

  public stopSynthesis(): void {
    if (this.noiseSource) {
      try { this.noiseSource.stop(); this.noiseSource.disconnect(); } catch { /* ignore */ }
      this.noiseSource = null;
    }
    if (this.lfo1) {
      try { this.lfo1.stop(); this.lfo1.disconnect(); } catch { /* ignore */ }
      this.lfo1 = null;
    }
    if (this.lfo2) {
      try { this.lfo2.stop(); this.lfo2.disconnect(); } catch { /* ignore */ }
      this.lfo2 = null;
    }
  }
}

/**
 * 8. Cozy Fireplace Generator
 * Warm hearth ember roar + acoustic wood crackles & snaps.
 */
export class CozyFireplaceGenerator extends BaseProceduralGenerator {
  private bedSource: AudioBufferSourceNode | null = null;
  private crackleTimer: number | null = null;
  private crackleBuffer: AudioBuffer | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;

    // 1. Warm burning embers low rumble
    const frames = sr * 8;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    let lastL = 0, lastR = 0;
    for (let i = 0; i < frames; i++) {
      lastL = (lastL + 0.015 * (Math.random() * 2 - 1)) / 1.015;
      lastR = (lastR + 0.015 * (Math.random() * 2 - 1)) / 1.015;
      l[i] = lastL * 2.2;
      r[i] = lastR * 2.2;
    }

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(320, this.ctx.currentTime);

    this.bedSource = this.ctx.createBufferSource();
    this.bedSource.buffer = buffer;
    this.bedSource.loop = true;
    this.bedSource.connect(filter);
    filter.connect(this.outputGain);
    this.bedSource.start();

    // 2. Pre-generate acoustic micro-snap noise burst
    const snapFrames = Math.floor(sr * 0.02); // 20ms micro-burst
    this.crackleBuffer = this.ctx.createBuffer(1, snapFrames, sr);
    const snapData = this.crackleBuffer.getChannelData(0);
    for (let i = 0; i < snapFrames; i++) {
      const decay = Math.exp(-i / (sr * 0.003));
      snapData[i] = (Math.random() * 2 - 1) * decay;
    }

    this.scheduleCrackles();
  }

  private scheduleCrackles(): void {
    if (!this.running) return;

    const snaps = Math.floor(Math.random() * 3) + 1;
    for (let i = 0; i < snaps; i++) {
      const delay = Math.random() * 140;
      setTimeout(() => {
        if (this.running && this.crackleBuffer) this.triggerCrackle();
      }, delay);
    }

    const nextBatch = 80 + Math.random() * 180;
    this.crackleTimer = window.setTimeout(() => this.scheduleCrackles(), nextBatch);
  }

  private triggerCrackle(): void {
    if (!this.crackleBuffer) return;
    const now = this.ctx.currentTime;

    const source = this.ctx.createBufferSource();
    source.buffer = this.crackleBuffer;

    const bp = this.ctx.createBiquadFilter();
    bp.type = 'bandpass';
    // Frequency of dry pine snapping: 2.2k - 5.5k Hz
    const freq = 2200 + Math.random() * 3300;
    bp.frequency.setValueAtTime(freq, now);
    bp.Q.setValueAtTime(4.0 + Math.random() * 2.5, now);

    const gain = this.ctx.createGain();
    const amp = 0.06 + Math.random() * 0.12;
    gain.gain.setValueAtTime(amp, now);

    const pan = this.ctx.createStereoPanner();
    pan.pan.setValueAtTime(Math.random() * 1.4 - 0.7, now);

    source.connect(bp);
    bp.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    source.start(now);
  }

  public stopSynthesis(): void {
    if (this.crackleTimer) {
      clearTimeout(this.crackleTimer);
      this.crackleTimer = null;
    }
    if (this.bedSource) {
      try { this.bedSource.stop(); this.bedSource.disconnect(); } catch { /* ignore */ }
      this.bedSource = null;
    }
  }
}

/**
 * 9. Forest Wind Generator
 * 3 parallel resonant bandpass filters sweeping slowly across pink noise.
 * Sounds like cool mountain breeze whistling through pine needles.
 */
export class ForestWindGenerator extends BaseProceduralGenerator {
  private noiseSource: AudioBufferSourceNode | null = null;
  private lfo1: OscillatorNode | null = null;
  private lfo2: OscillatorNode | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;
    const frames = sr * 10;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    let b0L = 0, b1L = 0, b0R = 0, b1R = 0;
    for (let i = 0; i < frames; i++) {
      const wL = Math.random() * 2 - 1;
      const wR = Math.random() * 2 - 1;
      b0L = 0.96 * b0L + wL * 0.06;
      b1L = 0.94 * b1L + b0L * 0.10;
      b0R = 0.96 * b0R + wR * 0.06;
      b1R = 0.94 * b1R + b0R * 0.10;
      l[i] = b1L * 1.6;
      r[i] = b1R * 1.6;
    }

    this.noiseSource = this.ctx.createBufferSource();
    this.noiseSource.buffer = buffer;
    this.noiseSource.loop = true;

    // Dual resonant bandpass formants
    const bp1 = this.ctx.createBiquadFilter();
    bp1.type = 'bandpass';
    bp1.frequency.setValueAtTime(360, this.ctx.currentTime);
    bp1.Q.setValueAtTime(3.2, this.ctx.currentTime);

    const bp2 = this.ctx.createBiquadFilter();
    bp2.type = 'bandpass';
    bp2.frequency.setValueAtTime(840, this.ctx.currentTime);
    bp2.Q.setValueAtTime(4.0, this.ctx.currentTime);

    this.lfo1 = this.ctx.createOscillator();
    this.lfo1.type = 'sine';
    this.lfo1.frequency.setValueAtTime(0.09, this.ctx.currentTime); // gentle gust cycle

    const lfo1Gain = this.ctx.createGain();
    lfo1Gain.gain.setValueAtTime(180, this.ctx.currentTime);
    this.lfo1.connect(lfo1Gain);
    lfo1Gain.connect(bp1.frequency);

    this.lfo2 = this.ctx.createOscillator();
    this.lfo2.type = 'sine';
    this.lfo2.frequency.setValueAtTime(0.14, this.ctx.currentTime);

    const lfo2Gain = this.ctx.createGain();
    lfo2Gain.gain.setValueAtTime(240, this.ctx.currentTime);
    this.lfo2.connect(lfo2Gain);
    lfo2Gain.connect(bp2.frequency);

    this.noiseSource.connect(bp1);
    this.noiseSource.connect(bp2);
    bp1.connect(this.outputGain);
    bp2.connect(this.outputGain);

    this.noiseSource.start();
    this.lfo1.start();
    this.lfo2.start();
  }

  public stopSynthesis(): void {
    if (this.noiseSource) {
      try { this.noiseSource.stop(); this.noiseSource.disconnect(); } catch { /* ignore */ }
      this.noiseSource = null;
    }
    if (this.lfo1) {
      try { this.lfo1.stop(); this.lfo1.disconnect(); } catch { /* ignore */ }
      this.lfo1 = null;
    }
    if (this.lfo2) {
      try { this.lfo2.stop(); this.lfo2.disconnect(); } catch { /* ignore */ }
      this.lfo2 = null;
    }
  }
}

/**
 * 10. Night Crickets Generator
 * Organic nocturnal meadow chorus with realistic stereo wing stridulation pulses.
 */
export class NightCricketsGenerator extends BaseProceduralGenerator {
  private phraseTimer: number | null = null;
  private cricketBuffer: AudioBuffer | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;
    // Pre-render a natural cricket syllable train (4 micro-pulses, 4.6 kHz with natural sidebands)
    const dur = 0.08;
    const frames = Math.floor(sr * dur);
    this.cricketBuffer = this.ctx.createBuffer(1, frames, sr);
    const data = this.cricketBuffer.getChannelData(0);

    const carrier = 4650;
    const amRate = 42; // wing file tooth rub rate
    for (let i = 0; i < frames; i++) {
      const t = i / sr;
      const env = Math.sin((i / frames) * Math.PI);
      const am = 0.5 * (1 + Math.sin(2 * Math.PI * amRate * t));
      const tone = Math.sin(2 * Math.PI * carrier * t);
      data[i] = tone * am * env * 0.15;
    }

    this.schedulePhrase();
  }

  private schedulePhrase(): void {
    if (!this.running) return;

    // Phrase of 3 to 5 chirps
    const count = 3 + Math.floor(Math.random() * 3);
    for (let i = 0; i < count; i++) {
      const delay = i * 110;
      setTimeout(() => {
        if (this.running && this.cricketBuffer) this.triggerChirp();
      }, delay);
    }

    const nextPhrase = count * 110 + 700 + Math.random() * 1200;
    this.phraseTimer = window.setTimeout(() => this.schedulePhrase(), nextPhrase);
  }

  private triggerChirp(): void {
    if (!this.cricketBuffer) return;
    const now = this.ctx.currentTime;

    const source = this.ctx.createBufferSource();
    source.buffer = this.cricketBuffer;

    const pan = this.ctx.createStereoPanner();
    pan.pan.setValueAtTime(Math.random() * 1.4 - 0.7, now);

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.18 + Math.random() * 0.08, now);

    source.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    source.start(now);
  }

  public stopSynthesis(): void {
    if (this.phraseTimer) {
      clearTimeout(this.phraseTimer);
      this.phraseTimer = null;
    }
  }
}

/**
 * 11. Mountain Stream Generator
 * Continuous splashing fluid turbulence + resonant water droplet bubbles.
 */
export class MountainStreamGenerator extends BaseProceduralGenerator {
  private bedSource: AudioBufferSourceNode | null = null;
  private bubbleTimer: number | null = null;

  public startSynthesis(): void {
    const sr = this.ctx.sampleRate;
    const frames = sr * 8;
    const buffer = this.ctx.createBuffer(2, frames, sr);
    const l = buffer.getChannelData(0);
    const r = buffer.getChannelData(1);

    for (let i = 0; i < frames; i++) {
      l[i] = (Math.random() * 2 - 1) * 0.18;
      r[i] = (Math.random() * 2 - 1) * 0.18;
    }

    const bp = this.ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.setValueAtTime(740, this.ctx.currentTime);
    bp.Q.setValueAtTime(1.6, this.ctx.currentTime);

    this.bedSource = this.ctx.createBufferSource();
    this.bedSource.buffer = buffer;
    this.bedSource.loop = true;
    this.bedSource.connect(bp);
    bp.connect(this.outputGain);
    this.bedSource.start();

    this.scheduleBubbles();
  }

  private scheduleBubbles(): void {
    if (!this.running) return;

    const now = this.ctx.currentTime;
    const duration = 0.035 + Math.random() * 0.04;

    // Resonant acoustic cavity excitation
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const pan = this.ctx.createStereoPanner();

    const fStart = 850 + Math.random() * 600;
    const fEnd = 500 + Math.random() * 300;

    osc.type = 'sine';
    osc.frequency.setValueAtTime(fStart, now);
    osc.frequency.exponentialRampToValueAtTime(fEnd, now + duration);

    gain.gain.setValueAtTime(0.04 * (Math.random() * 0.5 + 0.5), now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);

    pan.pan.setValueAtTime(Math.random() * 1.6 - 0.8, now);

    osc.connect(gain);
    gain.connect(pan);
    pan.connect(this.outputGain);

    osc.start(now);
    osc.stop(now + duration);

    const nextDelay = 45 + Math.random() * 95;
    this.bubbleTimer = window.setTimeout(() => this.scheduleBubbles(), nextDelay);
  }

  public stopSynthesis(): void {
    if (this.bubbleTimer) {
      clearTimeout(this.bubbleTimer);
      this.bubbleTimer = null;
    }
    if (this.bedSource) {
      try { this.bedSource.stop(); this.bedSource.disconnect(); } catch { /* ignore */ }
      this.bedSource = null;
    }
  }
}
